// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"AP Music Theory starts with fundamentals. You'll need fluency in reading pitch and rhythm in every clef.","blocks":[{"t":"key","text":"Know treble, bass, alto and tenor clefs. The alto clef (C clef) places middle C on the middle line; the tenor clef places middle C on the fourth line."},{"t":"p","text":"Meter: simple meters divide the beat into two (2/4, 3/4, 4/4); compound meters divide the beat into three (6/8, 9/8, 12/8). In 6/8, the beat is a dotted quarter note, with two beats per measure."},{"t":"p","text":"Rhythmic devices: syncopation (accents on weak beats), hemiola (a shift that makes duple feel in a triple meter), and anacrusis (a pickup note before the first full measure)."},{"t":"p","text":"Musical terms: tempo (allegro, andante), dynamics (piano = soft, forte = loud, crescendo = getting louder) and articulation (staccato = short, legato = smooth)."}]},{"say":"Scales, key signatures and intervals are the vocabulary of harmony. They must be automatic for the exam.","blocks":[{"t":"key","text":"Know all major and minor key signatures and the circle of fifths. Minor forms: natural, harmonic (raised 7th) and melodic (raised 6th and 7th ascending)."},{"t":"p","text":"Other scales: chromatic, whole-tone, pentatonic, and the modes (Dorian, Phrygian, Lydian, Mixolydian, Aeolian, Locrian)."},{"t":"p","text":"Intervals have size and quality: perfect, major, minor, augmented, diminished. Inverting an interval: the numbers add to 9 and qualities swap (major ↔ minor, augmented ↔ diminished, perfect stays perfect). A major 3rd inverts to a minor 6th."},{"t":"p","text":"Compound intervals are larger than an octave (a 10th is an octave plus a 3rd)."}]}],[{"say":"Chords and Roman numeral analysis are the heart of AP Music Theory.","blocks":[{"t":"key","text":"In major keys: I, ii, iii, IV, V, vi, vii°. In minor keys (with raised leading tone): i, ii°, III, iv, V, VI, vii°."},{"t":"p","text":"Seventh chord qualities: major seventh (IM7), dominant seventh (V7), minor seventh (ii7), half-diminished (viiø7) and fully diminished (vii°7)."},{"t":"p","text":"Inversions use figured bass: root position (5/3), first inversion (6 or 6/3), second inversion (6/4). For seventh chords: 7, 6/5, 4/3, 4/2."},{"t":"ex","problem":"Analyze G–B–D–F in C major.","steps":["Root G (degree 5), major triad with a minor 7th"],"answer":"V7"}]},{"say":"Part writing tests your ability to connect chords smoothly in four voices: soprano, alto, tenor and bass.","blocks":[{"t":"key","text":"Voice-leading rules (SATB):"},{"t":"list","items":["Keep voices within their ranges, and keep spacing between upper voices within an octave.","Avoid parallel perfect fifths and octaves between any two voices.","Resolve the leading tone up to the tonic (especially in the soprano).","Resolve the chordal seventh down by step.","In root-position triads, usually double the root; never double the leading tone.","Move voices by the smallest possible intervals (common tones stay)."]},{"t":"ex","problem":"Two voices move from C–G to D–A. What's the problem?","steps":["Both form perfect fifths moving in the same direction"],"answer":"Parallel fifths, which are forbidden"}]}],[{"say":"Cadences shape phrases, and nonchord tones add melodic interest. Both appear constantly on the exam.","blocks":[{"t":"key","text":"Cadences: perfect authentic (V–I, root position, tonic in soprano), imperfect authentic (V–I with other variations), half (ends on V), plagal (IV–I) and deceptive (V–vi)."},{"t":"p","text":"The cadential 6/4 (I6/4 resolving to V) decorates the dominant at cadences."},{"t":"p","text":"Nonchord tones (notes not in the chord): passing tone (step-step, same direction), neighbor tone (step away and back), suspension (held over, then resolves down), appoggiatura (leap then step), escape tone (step then leap), anticipation, and pedal tone."}]},{"say":"Secondary dominants borrow tension from other keys, and modulation moves the music to a new home.","blocks":[{"t":"key","text":"A secondary dominant is the dominant of a chord other than I, written V/x. In C major, V/V is D major (D–F♯–A), which resolves to G (V). Secondary leading-tone chords are vii°/x."},{"t":"p","text":"Accidentals that don't belong to the key often signal secondary dominants."},{"t":"p","text":"Modulation changes the key. Common pivot-chord modulations move to closely related keys (those whose key signatures differ by one accidental, like C major to G major or A minor). A pivot chord functions in both keys."},{"t":"ex","problem":"In C major, what chord is V/ii?","steps":["ii is D minor; its dominant is A major"],"answer":"A–C♯–E (A major)"}]}],[{"say":"Modes and form expand your analysis beyond chords to the big picture of a piece.","blocks":[{"t":"key","text":"Modes from the major scale: Ionian (major), Dorian (minor with raised 6th), Phrygian (minor with lowered 2nd), Lydian (major with raised 4th), Mixolydian (major with lowered 7th), Aeolian (natural minor), Locrian (diminished)."},{"t":"p","text":"Phrase structure: a period has an antecedent phrase (ending with a weak cadence) and a consequent phrase (ending with a strong cadence). Parallel periods begin the same way; contrasting periods don't."},{"t":"p","text":"Forms: binary (rounded or simple), ternary, rondo, theme and variations, and sonata form."},{"t":"p","text":"Melodic devices: sequence (a pattern repeated at different pitch levels), inversion, augmentation and diminution."}]},{"say":"Half of AP Music Theory is listening and singing. Train your ears every day.","blocks":[{"t":"key","text":"The exam includes melodic and harmonic dictation (writing down what you hear), sight-singing, part writing from figured bass and Roman numerals, and multiple-choice listening and analysis."},{"t":"p","text":"Strategies:"},{"t":"list","items":["Dictation: find the key and meter first, write the rhythm, then the contour, then exact pitches. Use solfège (do, re, mi…) or scale-degree numbers.","Harmonic dictation: write the bass line first, then identify Roman numerals; listen for cadences.","Sight-singing: establish the key, sing the scale and tonic triad, keep a steady beat, and sing even if you make a mistake.","Part writing: check for parallel fifths and octaves, voice ranges, doubling and resolution of tendency tones."]}]}]];
export default text;
